import 'package:device_info_plus/device_info_plus.dart';import 'package:dio/dio.dart';import 'package:flutter_secure_storage/flutter_secure_storage.dart';import 'package:package_info_plus/package_info_plus.dart';import 'config.dart';
class Api {Api(this.storage):dio=Dio(BaseOptions(baseUrl:AppConfig.apiUrl,connectTimeout:const Duration(seconds:15),receiveTimeout:const Duration(seconds:20)));final FlutterSecureStorage storage;final Dio dio;Future<void> init()async{final android=await DeviceInfoPlugin().androidInfo;final p=await PackageInfo.fromPlatform();dio.interceptors.add(InterceptorsWrapper(onRequest:(o,h)async{final token=await storage.read(key:'token');if(token!=null)o.headers['Authorization']='Bearer $token';o.headers.addAll({'Accept':'application/json','X-Device-Identifier':await _deviceId(),'X-Device-Name':android.model,'X-Android-Version':android.version.release,'X-App-Version':p.version});h.next(o);},onError:(e,h)async{if(e.response?.statusCode==401)await storage.delete(key:'token');h.next(e);}));}Future<String> _deviceId()async{var id=await storage.read(key:'device_id');if(id==null){id=DateTime.now().microsecondsSinceEpoch.toString();await storage.write(key:'device_id',value:id);}return id;}}
